// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {TPlusUUPSUpgradeable} from "./utils/TPlusUUPSUpgradeable.sol";

/**
 * @title Registry
 * @notice Central registry for managing assets and associated risk parameters across multiple chains.
 * @dev Uses admin and multisig roles to control sensitive operations like asset registration and risk configuration.
 *
 * ## Asset Registry
 *
 * Assets are organized by a uint16 index. Each index represents a **fungible asset class** —
 * not a single token, but all representations of that asset across chains. For example:
 *
 *   - Index 0: USD — USDC on Ethereum, USDC on Solana, USDT on Ethereum, etc.
 *   - Index 1: ETH — WETH on Ethereum, WETH on Arbitrum, etc.
 *
 * Once an index is assigned, it is **permanent**. There is no mechanism to remove or reorder
 * assets; indices are append-only and monotonically increasing. This invariant is critical
 * because external systems (settlement, accounting) depend on index stability.
 *
 * **Important**: There is no on-chain enforcement that all entries under an index are truly
 * fungible with each other. It is the risk manager's responsibility to ensure that only
 * fungible representations of the same asset class are registered under a given index.
 * Registering a non-fungible token (e.g. a meme coin) under the USD index would be an
 * operational error with serious consequences.
 */
contract Registry is TPlusUUPSUpgradeable {
    /// @notice Timelock on scheduled upgrades.
    uint64 internal constant UPGRADE_DELAY_SECONDS = 2 days;

    /// @notice Address of the admin; primarily used for initial setup.
    address public admin;

    /// @notice Multisig wallet address responsible for managing risk-related configurations.
    address public riskManagerMultisig;

    /// @notice Number of seconds to wait before new risk parameters become effective
    uint256 public riskParameterChangeDelaySeconds;

    /// @notice Mapping of asset index to new risk parameters to be applied to the registry, but only after they become eligible
    mapping(uint16 => PendingRiskParameters) public pendingRiskParameters;

    /// @notice Mapping of asset index to associated risk parameters.
    mapping(uint16 => RiskParameters) public riskParameters;

    /// @notice Registry of all registered assets and associated chain data.
    AssetRegistry assets;

    /// @notice Reverse mapping: routingId => vmId => assetAddress => asset index + 1 (0 means not found).
    mapping(uint64 => mapping(uint64 => mapping(bytes32 => uint256))) assetIndexLookup;

    /// @notice Account for receiving fees and paying rewards.
    bytes32 public feeAccount;

    /// @notice Withdrawal delay parameters, used to calculate delays between request and execution of withdrawals.
    WithdrawalDelayParameters withdrawalDelayParameters;

    /// @notice Pending withdrawal delay parameters to be applied after the delay period.
    PendingWithdrawalDelayParameters public pendingWithdrawalDelayParameters;

    /// @notice Signals that the maximum deposit has changed for a given asset
    event MaxDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Signals that the maximum hourly deposit has changed for a given asset
    event Max1HrDepositChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Signals that the minimum weight has changed for a given asset
    event MinWeightChanged(ChainId chain, uint16 index, uint256 previous, uint256 current);

    /// @notice Defines risk-related configuration parameters for an asset.
    struct RiskParameters {
        /// @notice Percentage of asset value that can be counted as collateral (e.g., 90 = 90%).
        uint8 collateralFactor;

        /// @notice Percentage multiplier applied to liabilities for risk calculations (e.g., 90 = 90%).
        uint8 liabilityFactor;

        /// @notice Maximum allowable collateral amount for this asset. May be unenforced on-chain.
        uint256 maxCollateral;

        /// @notice Maximum total open interest allowed for derivatives positions.
        uint256 maxOpenInterest;

        /// @notice Maximum open interest allowed for spot positions.
        uint256 maxSpotOpenInterest;

        /// @notice Maximum allowed utilization ratio of available liquidity.
        uint256 maxUtilization;

        /// @notice If true, asset can only be used in isolated margin mode.
        bool isolatedOnly;

        /// @notice Utilization points where the interest rate curve slope changes, scaled in 1/100th of a basis point.
        uint256[] interestKinks;

        /// @notice Interest rates corresponding to `interestKinks`, scaled in 1/100th of a basis point.
        uint256[] kinkInterestRates;

        /// @notice USD-denominated utilization kink points, scaled in 1/100th of a basis point.
        uint256[] usdInterestKinks;

        /// @notice USD-denominated interest rates corresponding to `usdInterestKinks`, scaled in 1/100th of a basis point.
        uint256[] usdKinkInterestRates;

        /// @notice Multiplier applied to skew-based pricing adjustments, scaled in 1/100th of a basis point.
        uint256 skewModifier;

        /// @notice Skew threshold at which maximum skew adjustment applies, scaled in 1/100th of a basis point.
        uint256 skewCliff;

        /// @notice Base funding rate applied regardless of skew direction, scaled in 1/100th of a basis point.
        int256 baseFundingRate;

        /// @notice Maximum allowed premium adjustment, scaled in 1/100th of a basis point.
        uint256 premiumClamp;

        /// @notice Maximum premium impact applied during initial margin calculation, scaled in 1/100th of a basis point.
        uint256[] initialMarginClamps;

        /// @notice Multipliers applied to position size when calculating initial margin, scaled in 1/100th of a basis point.
        uint256[] initialMarginFactors;

        /// @notice Maximum absolute funding rate allowed, scaled in 1/100th of a basis point.
        uint256 maxFundingRate;

        /// @notice Maximum interest rate applied at full utilization, scaled in 1/100th of a basis point.
        uint256 maxUtilizationRate;

        /// @notice Additional safety buffer multiplier applied to risk calculations, scaled in 1/100th of a basis point.
        uint256 bufferMultiple;

        /// @notice Minimum USD-denominated balance required for sub-accounts, using 18 decimals.
        uint256 minSubAccountBalance;

        /// @notice Maximum notional (USD, 18 decimals) that auto-deleverage may close
        /// for this asset in a single pass. Zero DISABLES auto-deleverage for the
        /// asset: no ADL runs until a cap is set. Appended last so existing stored
        /// RiskParameters stay layout-compatible (they read 0, i.e. ADL disabled).
        uint256 maxAdl;
    }

    struct PendingRiskParameters {
        RiskParameters parameters;
        uint256 validAfter;
    }

    /**
     * @notice Struct for managing a list of registered assets.
     * @dev Assets are stored by index and can span multiple chains.
     *      Indices are append-only — once assigned, an asset's index never changes.
     *      See contract-level documentation for the index convention (e.g. 0 = USD).
     */
    struct AssetRegistry {
        uint256 count; // Total number of assets.
        uint256 totalEntries; // Total number of (chain, address) entries across all assets.
        mapping(uint16 => Asset) registry; // Mapping from index to asset struct.
    }

    struct WithdrawalDelayParameters {
        /// @notice Minimum delay for zero cumulative, in seconds.
        uint256 minDelay;

        /// @notice Maximum delay cap, in seconds.
        uint256 maxDelay;

        /// @notice Cumulative capacity thresholds, scaled in 1/100th of a basis point.
        uint256[] delayClamps;

        /// @notice Delay duration at each clamp, in seconds.
        uint256[] delayValues;

        /// @notice Floor for the potential function denominator.
        uint256 capFloor;
    }

    struct PendingWithdrawalDelayParameters {
        WithdrawalDelayParameters parameters;
        uint256 validAfter;
    }

    /**
     * @notice Struct for identifying a chain.
     */
    struct ChainId {
        // The routing ID e.g. 0=EVM style chains.
        uint64 routingId;

        // e.g. EVM chainId.
        uint64 vmId;
    }

    /**
     * @notice Struct representing an asset across multiple chains and addresses.
     */
    struct Asset {
        // Routing ID => Chain ID => Address => AssetData.
        mapping(uint64 => mapping(uint64 => mapping(bytes32 => AssetData))) data;

        // List of all known chain IDs for this asset.
        ChainId[] chains;

        // Parallel array of asset addresses, one per chain entry.
        bytes32[] addresses;
    }

    /**
     * @notice Chain-specific metadata for an asset.
     * @dev Uses bytes32 for `assetAddress` to support non-EVM chains like Solana.
     */
    struct AssetData {
        uint16 index;
        bytes32 assetAddress;
        ChainId chainId;
        uint256 maxDeposits; // Cap on deposits (collateral cap).
        uint256 max1hrDeposits; // Cap on fungible deposits over one hour
        uint256 minWeight; // Raw weight value (not percentage)
    }

    /// @notice Reverts if caller is not the admin.
    error NotAdmin();

    /// @notice Reverts if there is are no risk parameters queued for the specified asset
    error NoPendingRiskParameters(uint16 asset);

    /// @notice Reverts if the pending risk parameters are not yet eligible for application
    error TooSoon(uint16 asset, uint256 eligibleAt);

    /// @notice Reverts if caller is not the risk manager multisig.
    error NotRiskManager();

    /// @notice Reverts if the asset index is out of bounds.
    error IndexOutOfBounds();

    /// @notice Reverts if the collateral factor (CF) specified as part of risk parameters is greater than one
    error InvalidCollateralFactor();

    /// @notice Reverts if the liability factor (LF) specified as part of risk parameters is greater than one
    error InvalidLiabilityFactor();

    /// @notice Reverts if the utilization cap specified as part of risk parameters is greater than one
    error InvalidUtilizationCap();

    /// @notice Reverts if the funding rate cap specified as part of risk parameters is greater than ~1000% APR
    error InvalidMaxFundingRate();

    /// @notice Reverts if the utilization rate cap specified as part of risk parameters is greater than ~1000% APR
    error InvalidMaxUtilizationRate();

    /// @notice Reverts if the buffer multiple value is less than 1% or greater than 2%.
    error InvalidBufferMultiple();

    /// @notice Reverts if the skew modifier specified as part of risk parameters exceeds 1e6.
    error InvalidSkewModifier();

    /// @notice Reverts if the skew cliff specified as part of risk parameters exceeds 1e6.
    error InvalidSkewCliff();

    /// @notice Reverts if the base funding rate specified as part of risk parameters exceeds 1e6.
    error InvalidBaseFundingRate();

    /// @notice Reverts if the premium clamp specified as part of risk parameters exceeds 1e6.
    error InvalidPremiumClamp();

    /// @notice Reverts if the interest kinks specified as part of risk parameters are not increasing from 0 to 1
    error InvalidInterestKinks();

    /// @notice Reverts if the interest rates specified as part of risk parameters are not increasing
    error InvalidRateInterestKinks();

    /// @notice Reverts if the USD-denominated interest kinks specified as part of risk parameters are not increasing from 0 to 1
    error InvalidUSDInterestKinks();

    /// @notice Reverts if the USD-denominated interest rates specified as part of risk parameters are not increasing
    error InvalidUSDRateInterestKinks();

    /// @notice Reverts if the size of the initial margin clamps does not match the size of the initial margin factors (specified as part of risk parameters)
    error InvalidInitialMarginsConfiguration();

    /// @notice Reverts if the initial margin clamps specified as part of risk parameters are not increasing or are above 100
    error InvalidInitialMarginsClamps();

    /// @notice Reverts if the initial margin clamps specified as part of risk parameters are not decreasing or are above 100
    error InvalidInitialMarginsFactors();

    /// @notice Reverts if the withdrawal delay clamps and values arrays have different lengths.
    error InvalidWithdrawalDelayConfiguration();

    /// @notice Reverts if the withdrawal delay clamps are not monotonically increasing from zero.
    error InvalidWithdrawalDelayClamps();

    /// @notice Reverts if the withdrawal delay values are not monotonically increasing.
    error InvalidWithdrawalDelayValues();

    /// @notice Reverts if minDelay > maxDelay.
    error InvalidWithdrawalDelayBounds();

    /// @notice Reverts if a withdrawal delay value is outside [minDelay, maxDelay].
    error WithdrawalDelayValueOutOfBounds();

    /// @notice Reverts if there are no pending withdrawal delay parameters.
    error NoPendingWithdrawalDelayParameters();

    /// @notice Reverts if the pending withdrawal delay parameters are not yet eligible.
    error WithdrawalDelayParametersTooSoon(uint256 eligibleAt);

    /// @notice Reverts if an address is zero.
    error ZeroAddress();

    /// @notice Reverts if the risk manager is not set.
    error RiskManagerNotSet();

    constructor(address _admin, uint256 _riskParameterChangeDelaySeconds) {
        _initialize(_admin, _riskParameterChangeDelaySeconds);
    }

    /**
     * @notice Initializes contract configuration for proxy deployments.
     */
    function initialize(address _admin, uint256 _riskParameterChangeDelaySeconds)
        external
        initializer
    {
        _initialize(_admin, _riskParameterChangeDelaySeconds);
    }

    function _initialize(address _admin, uint256 _riskParameterChangeDelaySeconds) internal {
        admin = _admin;
        riskParameterChangeDelaySeconds = _riskParameterChangeDelaySeconds;
    }

    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        // Once configured, the risk manager multisig becomes the sole upgrade authority.
        if (riskManagerMultisig != address(0)) return caller == riskManagerMultisig;
        return caller == admin;
    }

    function _upgradeDelaySeconds() internal pure override returns (uint64) {
        return UPGRADE_DELAY_SECONDS;
    }

    /**
     * @notice Updates the risk manager multisig address.
     * @param multisig The new address to set.
     * @dev Reverts with `NotAdmin`; Only the admin can set a risk manager.
     */
    function setRiskManagerMultisig(address multisig) external {
        if (msg.sender != admin) revert NotAdmin();
        riskManagerMultisig = multisig;
    }

    /**
     * @notice Updates the admin address.
     * @param newAdmin The new admin address.
     * @dev Reverts with `NotAdmin`; Only the admin can set a new admin.
     * @dev The new administrator address is allowed to be the null address.
     *      Setting the administrator to this address disables administration
     *      of the registry contract.
     */
    function setAdmin(address newAdmin) external {
        if (msg.sender != admin) revert NotAdmin();
        if (newAdmin == address(0) && riskManagerMultisig == address(0)) {
            revert RiskManagerNotSet();
        }
        admin = newAdmin;
    }

    /**
     * @notice Sets or updates asset data for a specific asset index and chain.
     * @dev Automatically adds new assets or chain instances if not already present.
     *      New indices can only be created sequentially (data.index == assets.count).
     *      Existing entries are updated in-place; indices cannot be removed or reordered.
     *
     *      WARNING: There is no on-chain check that the asset being added is fungible with
     *      other entries at the same index. The caller must ensure correctness — e.g. do not
     *      register a non-USD token under the USD index.
     * @param data The chain-specific asset data.
     * @dev Reverts with `NotRiskManager`; Only the risk manager can set asset data.
     */
    function setAssetData(AssetData memory data) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        if (data.index > assets.count) revert IndexOutOfBounds();

        // Prevent registering asset with zero-address. Zero-address means that asset
        // has not yet been set on a chain, where is this case it has.
        if (data.assetAddress == bytes32(0)) revert ZeroAddress();

        Asset storage reg = assets.registry[data.index];

        uint64 routingId = data.chainId.routingId;
        uint64 vmId = data.chainId.vmId;

        bool isNewEntry = reg.data[routingId][vmId][data.assetAddress].assetAddress == bytes32(0);
        reg.data[routingId][vmId][data.assetAddress] = data;

        if (isNewEntry) {
            if (data.index == assets.count) {
                assets.count += 1;
            }
            reg.chains.push(data.chainId);
            reg.addresses.push(data.assetAddress);
            assets.totalEntries += 1;
            // Store index + 1 so that 0 means "not found".
            assetIndexLookup[routingId][vmId][data.assetAddress] = uint256(data.index) + 1;
        }
    }

    function setMaxDeposits(
        ChainId calldata chainId,
        uint16 index,
        bytes32 assetAddress,
        uint256 newMaxDeposit
    ) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        require(index < assets.count, "!asset");

        uint64 routingId = chainId.routingId;
        uint64 vmId = chainId.vmId;

        uint256 oldMaxDeposit =
            assets.registry[index].data[routingId][vmId][assetAddress].maxDeposits;
        assets.registry[index].data[routingId][vmId][assetAddress].maxDeposits = newMaxDeposit;
        emit MaxDepositChanged(chainId, index, oldMaxDeposit, newMaxDeposit);
    }

    function setMax1HrDeposits(
        ChainId calldata chainId,
        uint16 index,
        bytes32 assetAddress,
        uint256 newMaxDeposit
    ) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        require(index < assets.count, "!asset");

        uint64 routingId = chainId.routingId;
        uint64 vmId = chainId.vmId;

        uint256 oldMaxDeposit =
            assets.registry[index].data[routingId][vmId][assetAddress].max1hrDeposits;
        assets.registry[index].data[routingId][vmId][assetAddress].max1hrDeposits = newMaxDeposit;
        emit Max1HrDepositChanged(chainId, index, oldMaxDeposit, newMaxDeposit);
    }

    function setMinWeight(
        ChainId calldata chain,
        uint16 index,
        bytes32 assetAddress,
        uint256 newMinWeight
    ) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        require(index < assets.count, "!asset");
        uint256 oldMinWeight =
            assets.registry[index].data[chain.routingId][chain.vmId][assetAddress].minWeight;
        assets.registry[index].data[chain.routingId][chain.vmId][assetAddress].minWeight =
        newMinWeight;
        emit MinWeightChanged(chain, index, oldMinWeight, newMinWeight);
    }

    /**
     * @notice Retrieves asset data for a specific asset, chain, and address.
     * @param chainId the chain ID to query.
     * @param index The asset index to query.
     * @param assetAddress The asset address to query.
     * @return The corresponding AssetData struct.
     */
    function getAssetData(ChainId calldata chainId, uint16 index, bytes32 assetAddress)
        external
        view
        returns (AssetData memory)
    {
        return assets.registry[index].data[chainId.routingId][chainId.vmId][assetAddress];
    }

    /**
     * @notice Returns all registered asset data across all chains.
     * @return An array of AssetData structs.
     * @param start The start index (inclusive).
     * @param end The end index (not-inclusive).
     */
    function getAssets(uint16 start, uint16 end) external view returns (AssetData[] memory) {
        uint256 totalEntries = assets.totalEntries;

        // Return empty array if start >= totalEntries
        if (start >= totalEntries) {
            return new AssetData[](0);
        }

        if (end > totalEntries) {
            // casting to 'uint16' is safe because we won't ever that many assets.
            // forge-lint: disable-next-line(unsafe-typecast)
            end = uint16(totalEntries);
        }

        if (end < start) {
            return new AssetData[](0);
        }

        uint16 length = end - start;
        AssetData[] memory result = new AssetData[](length);

        uint256 r = 0;
        uint256 resIdx = 0;

        for (uint16 i = 0; i < assets.count && resIdx < length; ++i) {
            Asset storage asset = assets.registry[i];
            uint256 chainsLen = asset.chains.length;

            for (uint256 c = 0; c < chainsLen && resIdx < length; ++c) {
                if (r >= start && r < end) {
                    ChainId storage chain = asset.chains[c];
                    result[resIdx++] = asset.data[chain.routingId][chain.vmId][asset.addresses[c]];
                }

                ++r;
            }
        }

        return result;
    }

    /**
     * @notice Returns the asset index for a given chain and address.
     * @param chainId The chain ID to search.
     * @param assetAddress The asset address (as bytes32).
     * @return The index of the asset, or `type(uint32).max` if not found.
     */
    function getAssetIndex(ChainId calldata chainId, bytes32 assetAddress)
        external
        view
        returns (uint32)
    {
        uint256 stored = assetIndexLookup[chainId.routingId][chainId.vmId][assetAddress];
        if (stored == 0) {
            return type(uint32).max;
        }
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint32(stored - 1);
    }

    /**
     * @notice Sets pending risk parameters for a specific asset index.
     * @param index The asset index.
     * @param parameters The risk parameters to set
     * @dev Reverts with `NotRiskManager`; Only the risk manager can set risk parameters.
     * @dev Reverts with `"!asset"` if index >= assets.count.
     */
    function setPendingRiskParameters(uint16 index, RiskParameters memory parameters) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        require(index < assets.count, "!asset");
        validateRiskParameters(parameters);
        PendingRiskParameters memory pendingParams = PendingRiskParameters({
            parameters: parameters, validAfter: block.timestamp + riskParameterChangeDelaySeconds
        });
        pendingRiskParameters[index] = pendingParams;
    }

    /**
     * @notice Applies the pending risk parameters for the specified asset if they exist.
     * @param index The asset index.
     * @dev Reverts with `"!asset"` if index >= assets.count.
     * @dev Reverts with `NoPendingRiskParameters` if there are no pending risk parameters for the specified asset
     * @dev Reverts with `TooSoon` if the pending risk parameters are not yet eligible
     */
    function applyPendingRiskParameters(uint16 index) external {
        require(index < assets.count, "!asset");
        PendingRiskParameters memory pendingParams = pendingRiskParameters[index];
        if (pendingParams.validAfter == 0) revert NoPendingRiskParameters(index);
        if (pendingParams.validAfter > block.timestamp) {
            revert TooSoon(index, pendingParams.validAfter);
        }
        RiskParameters memory params = pendingParams.parameters;
        validateRiskParameters(params);
        riskParameters[index] = params;
        delete pendingRiskParameters[index];
    }

    function validateRiskParameters(RiskParameters memory params) public pure {
        if (params.collateralFactor > 1e2) revert InvalidCollateralFactor();
        if (params.liabilityFactor > 1e2) revert InvalidLiabilityFactor();
        if (params.maxUtilization > 1e18) revert InvalidUtilizationCap();
        if (params.maxFundingRate > 1142) revert InvalidMaxFundingRate();
        if (params.maxUtilizationRate > 1142) revert InvalidMaxUtilizationRate();

        if (params.skewModifier > 1e6) revert InvalidSkewModifier();
        if (params.skewCliff > 1e6) revert InvalidSkewCliff();
        if (params.baseFundingRate > 1e6 || params.baseFundingRate < -1e6) {
            revert InvalidBaseFundingRate();
        }
        if (params.premiumClamp > 1e6) revert InvalidPremiumClamp();

        uint256 bufferMultiple = params.bufferMultiple;
        if (bufferMultiple < 1e6 || bufferMultiple > 2e6) revert InvalidBufferMultiple();

        if (!validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.interestKinks)) {
            revert InvalidInterestKinks();
        }
        if (!validateLastIsOne(params.interestKinks)) revert InvalidInterestKinks();
        if (!validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.usdInterestKinks)) {
            revert InvalidUSDInterestKinks();
        }
        if (!validateLastIsOne(params.usdInterestKinks)) revert InvalidUSDInterestKinks();

        if (!validateIncreasesAndBelowOne(params.kinkInterestRates)) {
            revert InvalidRateInterestKinks();
        }
        if (!validateIncreasesAndBelowOne(params.usdKinkInterestRates)) {
            revert InvalidUSDRateInterestKinks();
        }

        if (params.initialMarginClamps.length != params.initialMarginFactors.length) {
            revert InvalidInitialMarginsConfiguration();
        }
        if (!validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.initialMarginClamps)) {
            revert InvalidInitialMarginsClamps();
        }
        if (!validateIMFactors(params.initialMarginFactors)) revert InvalidInitialMarginsFactors();
    }

    /**
     * @notice Last point should be (1_000_000)
     */
    function validateLastIsOne(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        return len != 0 && xs[len - 1] == 1_000_000;
    }

    /**
     * @notice Validate that a series of values is increasing
     */
    function validateIncreases(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 prev = 0;

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur < prev) return false;
            prev = cur;
        }

        return true;
    }

    /**
     * @notice Validate that a series of values is increasing and every element is <= 1 (1_000_000).
     * @dev The upper bound keeps each element well inside u32 so the off-chain decoder cannot panic.
     */
    function validateIncreasesAndBelowOne(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 prev = 0;

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur < prev) return false;
            if (cur > 1_000_000) return false;
            prev = cur;
        }

        return true;
    }

    /**
     * @notice IM clamps must always increase and be <= 1 (1_000_000), and first point must be 0
     */
    function validateStartAtZeroIsAlwaysBelowOneAndIncreases(uint256[] memory xs)
        internal
        pure
        returns (bool)
    {
        uint256 len = xs.length;
        uint256 prev = 0;

        if (len == 0 || xs[0] != 0) {
            return false;
        }

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur > 1_000_000) return false;
            if (cur < prev) return false;
            prev = cur;
        }

        return true;
    }

    /**
     * @notice IM factors must always decreases and be < 1 (1_000_000)
     */
    function validateIMFactors(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 prev = 999_999;

        for (uint256 i; i < len; ++i) {
            uint256 cur = xs[i];
            if (cur > prev) return false;
            prev = cur;
        }

        return true;
    }

    function sumIsOne(uint256[] memory xs) internal pure returns (bool) {
        uint256 len = xs.length;
        uint256 sum;

        for (uint256 i; i < len; ++i) {
            sum += xs[i];
            if (sum > 1e6) return false;
        }

        return sum == 1e6;
    }

    /**
     * @notice Returns the full list of risk parameters for all registered assets.
     * @return An array of RiskParameters.
     * @param start The start index (inclusive).
     * @param end The end index (not inclusive).
     */
    function getRiskParameters(uint16 start, uint16 end)
        external
        view
        returns (RiskParameters[] memory)
    {
        uint16 count = uint16(assets.count);

        if (start >= count) {
            return new RiskParameters[](0);
        }

        if (end > count) {
            end = count;
        }

        if (end < start) {
            return new RiskParameters[](0);
        }

        uint256 length = end - start;
        RiskParameters[] memory result = new RiskParameters[](length);

        for (uint16 i = 0; i < length; ++i) {
            result[i] = riskParameters[start + i];
        }

        return result;
    }

    /**
     * @notice Sets the global fee account.
     * @param account The account.
     * @dev Reverts with `NotRiskManager`; Only the risk manager can set a new fee account.
     */
    function setFeeAccount(bytes32 account) external {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        feeAccount = account;
    }

    /**
     * @notice Get the global withdrawal delay parameters.
     */
    function getWithdrawalDelayParameters()
        external
        view
        returns (WithdrawalDelayParameters memory)
    {
        return withdrawalDelayParameters;
    }

    /**
     * @notice Queues new global withdrawal delay parameters with a time-lock.
     * @param parameters The parameters.
     * @dev Reverts with `NotRiskManager`; Only the risk manager can set new withdrawal delay parameters.
     */
    function setPendingWithdrawalDelayParameters(WithdrawalDelayParameters memory parameters)
        external
    {
        if (msg.sender != riskManagerMultisig) revert NotRiskManager();
        validateWithdrawalDelayParameters(parameters);
        pendingWithdrawalDelayParameters = PendingWithdrawalDelayParameters({
            parameters: parameters, validAfter: block.timestamp + riskParameterChangeDelaySeconds
        });
    }

    /**
     * @notice Applies the pending withdrawal delay parameters if they exist and are eligible.
     * @dev Reverts with `NoPendingWithdrawalDelayParameters` if none are queued.
     * @dev Reverts with `WithdrawalDelayParametersTooSoon` if not yet eligible.
     */
    function applyPendingWithdrawalDelayParameters() external {
        PendingWithdrawalDelayParameters memory pending = pendingWithdrawalDelayParameters;
        if (pending.validAfter == 0) revert NoPendingWithdrawalDelayParameters();
        if (pending.validAfter > block.timestamp) {
            revert WithdrawalDelayParametersTooSoon(pending.validAfter);
        }
        WithdrawalDelayParameters memory params = pending.parameters;
        validateWithdrawalDelayParameters(params);
        withdrawalDelayParameters = params;
        delete pendingWithdrawalDelayParameters;
    }

    /**
     * @notice Validates withdrawal delay parameters.
     * @param params The parameters to validate.
     */
    function validateWithdrawalDelayParameters(WithdrawalDelayParameters memory params)
        public
        pure
    {
        if (params.minDelay > params.maxDelay) revert InvalidWithdrawalDelayBounds();
        if (params.delayClamps.length != params.delayValues.length) {
            revert InvalidWithdrawalDelayConfiguration();
        }
        if (!validateStartAtZeroIsAlwaysBelowOneAndIncreases(params.delayClamps)) {
            revert InvalidWithdrawalDelayClamps();
        }
        if (!validateIncreases(params.delayValues)) {
            revert InvalidWithdrawalDelayValues();
        }
        for (uint256 i; i < params.delayValues.length; ++i) {
            if (params.delayValues[i] < params.minDelay || params.delayValues[i] > params.maxDelay)
            {
                revert WithdrawalDelayValueOutOfBounds();
            }
        }
    }
}

src/DepositVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {EfficientHashLib} from "solady/utils/EfficientHashLib.sol";
import {ECDSA} from "solady/utils/ECDSA.sol";
import {IAtomicSettlementCallback} from "./interfaces/IAtomicSettlementCallback.sol";
import {TPlusUUPSUpgradeable} from "./utils/TPlusUUPSUpgradeable.sol";

contract DepositVault is TPlusUUPSUpgradeable {
    /// @notice The number of decimals used by the clearing engine for normalized amounts.
    /// @dev Must stay in sync with the clearing engine's normalization logic.
    uint8 internal constant CLEARING_ENGINE_DECIMALS = 18;

    /// @notice Timelock on scheduled upgrades.
    uint64 internal constant UPGRADE_DELAY_SECONDS = 2 days;

    /**
     * @notice The admin approves settlements and withdrawals.
     * @dev Should be set to the DStack container shared secret address.
     */
    address public owner;

    /**
     * @notice The address responsible for adding or removing administrators
     * @dev In production, this will be an upgradeable proxy
     */
    address public credentialManager;

    /// @notice Domain separator used for signature verification. It should include the routing ID, the vm ID, this
    /// vault address, and the settlement schema version.
    bytes32 internal _domainSeparator;

    /// @notice Maps settler IDs to their executor addresses.
    mapping(bytes32 => SettlerInfo) settlerExecutorMap;

    /// @notice List of all approved settler IDs.
    bytes32[] public approvedSettlers;

    /// @notice Minimum number of administrator signatures to approve a withdrawal request
    uint256 public withdrawalQuorum;

    uint256 public credentialManagerChangeDelayBlocks;

    /// @notice Tracks which settler IDs have been approved.
    mapping(bytes32 => bool) internal settlerIsApproved;

    /**
     * @notice Maximum total tokens that can be settled in a single block for each token.
     * @dev Currently unused — implementation pending design finalization.
     */
    mapping(address => uint256) public settlementCaps;

    /// @notice Maps (settler ID, account_index) pairs to their queue of pending batch settlements.
    mapping(bytes32 => mapping(uint64 => PendingSettlement[])) public pendingSettlements;

    /// @notice Maps (settler ID, account_index) pairs to their settlement count (nonce).
    mapping(bytes32 => mapping(uint64 => uint64)) public settlementCounts;

    /// @notice Maps user ID pairs to their deposit count (nonce).
    mapping(bytes32 => uint64) public depositCounts;

    /// @notice Per-asset minimum amount required on a user's first deposit, in token native units.
    /// @dev A value of 0 disables first-deposit minimum enforcement for that token.
    mapping(address => uint256) public minFirstDepositAmounts;

    /// @notice Maps user ID to their withdrawal count (nonce).
    mapping(bytes32 => uint64) public withdrawalCounts;

    /// @notice Set of administrators
    address[] public administrators;

    // TODO: Delete before official production.
    mapping(address => bool) public canDeposit;

    /// @notice Block number of latest signature use
    uint256 public lastSignatureUse;

    /**
     * Makes the signature unambiguous that it is for settlements.
     */
    bytes32 public constant SETTLEMENT_TYPEHASH = keccak256("SettlementApprovalV2");

    /**
     * Makes the signature unambiguous that it is for withdrawals.
     */
    bytes32 constant WITHDRAWAL_TYPEHASH = keccak256("WithdrawalApprovalV1");

    enum SettlementMode {
        Spot,
        Margin
    }

    /// @notice Request for settlement
    /// @dev Used for all forms of settlement supported by the t+ vault
    struct Settlement {
        /// @notice Address of the token to be sent OUT from the vault
        address tokenOut;
        /// @notice Quantity of the output token to be sent OUT from the vault
        uint256 amountOut;
        /// @notice Address of the token to be sent IN to the vault
        address tokenIn;
        /// @notice Quantity of the input token to be sent IN from the vault
        uint256 amountIn;
        /// @notice Explicit CE settlement mode.
        SettlementMode mode;
        /// @notice Unique identifier of the user being settled
        bytes32 user;
        /// @notice Account index of the user being settled
        uint64 account;
        /// @notice Settlement nonce for this request
        uint64 nonce;
        /// @notice Unix timestamp (seconds) at which this request is valid until (i.e.,
        ///         immediately after this time this request is considered
        ///         expired). Compared against `block.timestamp`.
        uint256 validUntil;
    }

    /// @notice Request for settlement
    /// @dev Used for all forms of settlement supported by the t+ vault
    struct SettlementOrder {
        /// @notice Address of the token to be sent OUT from the vault
        address tokenOut;
        /// @notice Quantity of the output token to be sent OUT from the vault
        uint256 amountOut;
        /// @notice Address of the token to be sent IN to the vault
        address tokenIn;
        /// @notice Quantity of the input token to be sent IN from the vault
        uint256 amountIn;
        /// @notice Explicit CE settlement mode.
        SettlementMode mode;
        /// @notice Settlement nonce for this request
        uint64 nonce;
    }

    /// @notice A settlement request with associated signatures
    struct SignedSettlement {
        /// @notice Settlement request
        Settlement settlement;
        /// @notice Signature from the t+ Clearing Engine (CE)
        bytes clearingEngineSignature;
    }

    /// @notice A settlement request with associated signatures
    struct SignedSettlementOrder {
        /// @notice Settlement request
        SettlementOrder settlement;
        /// @notice Signature from the t+ Clearing Engine (CE)
        bytes clearingEngineSignature;
    }

    /**
     * @notice Stores pending settlements for a given (user ID, account_index) pair when batch settlement is used.
     * @dev Target is the address expected to execute the settlement.
     */
    struct PendingSettlement {
        SettlementOrder settlement;
        address target;
    }

    /// @notice Records a withdrawal.
    struct Withdrawal {
        address tokenAddress;
        uint256 amount;
        uint64 nonce;
    }

    /// @notice Information about a settler account.
    struct SettlerInfo {
        address[] executors;
        mapping(address => bool) isExecutor;
    }

    /// @notice Balance of a token for squashing purposes
    struct TokenSquashingBalance {
        /// @notice Address of the token that this balance represents
        address token;
        /// @notice Total quantity of tokens that the vault needs to receive
        uint256 input;
        /// @notice Total quantity of tokens that the vault needs to send
        uint256 output;
        /// @notice Net quantity of tokens that the vault needs to receive
        ///         (i.e., negative implies sending more tokens out than the
        ///         vault is receiving)
        int256 netAmount;
    }

    /// @notice Multisig signer configuration
    struct SignerConfig {
        bytes32 key;
        uint8 keyType;
        uint8 keyPrefix;
        uint32 weight;
        uint64 expiresAtNs;
        uint64 maxSigningWindowNs;
    }

    /// @notice Signals a settlement.
    event Settled(
        bytes32 indexed user,
        uint64 indexed account,
        uint256 indexed nonce,
        address tokenOut,
        uint256 amountOut,
        address tokenIn,
        uint256 amountIn,
        SettlementMode mode,
        bytes32 settler
    );

    /// @notice Indicates that the set of administrators has been cleared and is now empty
    event AdministratorSetReset();

    /// @notice Signals that the withdrawal quorum has changed
    event WithdrawalQuorumChanged(uint256 previous, uint256 current);

    /// @notice Signals that the credential manager address has changed
    event CredentialManagerChanged(address oldCredentialManager, address newCredentialManager);

    /// @notice Signals that a new administrator has been added to the vault
    event AdminAdded(address newAdmin, uint256 numAdminsAfter);

    /// @notice Signals a deposit
    event Deposited(
        bytes32 indexed user, uint256 indexed nonce, address indexed tokenAddress, uint256 amount
    );

    /// @notice Signals a deposit containing additional multisig signer information
    event DepositedWithConfig(
        bytes32 indexed user,
        uint256 indexed nonce,
        address indexed tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] signers,
        bytes masterConfigSignature
    );

    /// @notice Signals that the minimum first-deposit amount for a token has changed.
    event MinFirstDepositAmountChanged(
        address indexed tokenAddress, uint256 previous, uint256 current
    );

    /// @notice Signals a withdrawal.
    event Withdrew(
        bytes32 indexed user, uint256 indexed nonce, address tokenAddress, uint256 amount
    );

    /// @notice Reverts if the caller is not the owner.
    error NotOwner();

    /// @notice Reverts if the specified settler is not an approved settler on
    ///         this vault
    error SettlerNotApproved();

    /// @notice Reverts if the specified depositor is not approved.
    error DepositorNotApproved();

    /// @notice Reverts if the number of callback data payloads does not match
    ///         the number of settlement requests
    error PayloadMismatch();

    /// @notice Reverts if a settlement callback returns an insufficient input token amount
    error InsufficientAmountFromExecutor(uint256 actual, uint256 required);

    /// @notice Reverts if a settlement callback returns insufficient amount for a specific settlement
    error InsufficientCallbackReturnForSettlement(
        uint256 settlementIndex, uint256 actual, uint256 required
    );

    /// @notice Reverts if an insufficient number of blocks have elapsed since the last signature use
    error TooSoon();

    /// @notice Reverts if the caller is not the credential manager
    error NotCredentialManager();

    /// @notice Reverts if a new withdrawal quorum value is equal to zero
    error ZeroWithdrawalQuorum();

    /// @notice Reverts if insufficient administrators are provided when setting the administrators
    error InsufficientAdministrators(uint256 actual, uint256 required);

    /// @notice Reverts if the caller is not an admin.
    error NotAdmin();

    /// @notice Reverts if the caller is not the authorized executor.
    error NotExecutor();

    /// @notice Reverts if a signed operation is past its deadline.
    error Expired();

    /// @notice Reverts if the nonce used in a transaction is incorrect.
    error InvalidNonce(uint256 expected, uint256 given);

    /// @notice Reverts if the signature provided is invalid.
    error InvalidSignature();

    /// @notice Reverts if an order array is empty.
    error EmptyOrders();

    /// @notice Reverts when given the zero address.
    error ZeroAddress();

    /// @notice Reverts when given a zero amount.
    error ZeroAmount();

    /// @notice Reverts when normalizing the deposit amount to 18 decimals would overflow
    error NormalizationOverflow();

    /// @notice Reverts when the token does not implement decimals()
    error DecimalsCallFailed();

    /// @notice Reverts when the user's first deposit amount is below the configured minimum.
    error FirstDepositBelowMinimum(uint256 minimum, uint256 actual);

    /// @notice Reverts when normalizing a deposit amount to 18 decimals would round to zero.
    error NormalizationRoundsToZero();

    /// @notice Reverts when an insufficient number of signatures are provided for a withdrawal request
    error MissedQuorum(uint256 provided, uint256 required);

    /// @notice Reverts when caller is not authorized to configure vault-local settings.
    /// @dev Authorized callers are owner, credential manager, and vault administrators.
    error NotVaultConfigManager();

    constructor(address _owner, address _credentialManager) {
        _initialize(_owner, _credentialManager);
    }

    /**
     * @notice Initializes the contract and sets the owner.
     * @param _owner The address to set as the owner.
     * @param _credentialManager The address of the credential manager.
     * @dev Reverts with `ZeroAddress()` if `_owner` is null.
     * @dev Reverts with `ZeroAddress()` if `_credentialManager` is null.
     */
    function initialize(address _owner, address _credentialManager) external initializer {
        _initialize(_owner, _credentialManager);
    }

    function _initialize(address _owner, address _credentialManager) internal {
        if (_owner == address(0)) revert ZeroAddress();
        if (_credentialManager == address(0)) revert ZeroAddress();
        owner = _owner;
        credentialManager = _credentialManager;
        credentialManagerChangeDelayBlocks = 14_400;
    }

    function _isUpgradeAuthority(address caller) internal view override returns (bool) {
        return caller == owner || caller == credentialManager;
    }

    function _upgradeDelaySeconds() internal pure override returns (uint64) {
        return UPGRADE_DELAY_SECONDS;
    }

    function isAdministrator(address account) public view returns (bool) {
        for (uint256 i = 0; i < administrators.length; i++) {
            if (administrators[i] == account) return true;
        }

        return false;
    }

    /**
     * @notice Sets the owner of the vault.
     * @dev Reverts with `NotOwner`; Only the owner can set a new owner.
     */
    function setOwner(address newOwner) external {
        if (msg.sender != owner) revert NotOwner();
        if (newOwner == address(0)) revert ZeroAddress();
        owner = newOwner;
    }

    function setCredentialManager(address newCredentialManager) external {
        if (msg.sender != owner) revert NotOwner();
        if (newCredentialManager == address(0)) revert ZeroAddress();
        /* TODO(jmcph4): check against `latestApproval`! */
        if (block.number >= lastSignatureUse + credentialManagerChangeDelayBlocks) {
            revert TooSoon();
        }
        address oldCredentialManager = credentialManager;
        credentialManager = newCredentialManager;
        emit CredentialManagerChanged(oldCredentialManager, newCredentialManager);
    }

    function setAdministrators(address[] calldata newAdministrators, uint256 newWithdrawalQuorum)
        external
    {
        if (msg.sender != credentialManager) revert NotCredentialManager();
        if (newWithdrawalQuorum < 1) revert ZeroWithdrawalQuorum();
        if (newAdministrators.length < newWithdrawalQuorum) {
            revert InsufficientAdministrators(newAdministrators.length, newWithdrawalQuorum);
        }

        // It's critical there are no zero-addresses; otherwise, errored signatures may mistakenly pass.
        for (uint256 i = 0; i < newAdministrators.length; i++) {
            if (newAdministrators[i] == address(0)) revert ZeroAddress();
        }

        administrators = newAdministrators;
        emit AdministratorSetReset();

        for (uint256 i = 0; i < administrators.length; i++) {
            address currAdmin = administrators[i];
            emit AdminAdded(currAdmin, i + 1);
        }

        uint256 oldWithdrawalQuorum = withdrawalQuorum;
        withdrawalQuorum = newWithdrawalQuorum;
        if (oldWithdrawalQuorum != newWithdrawalQuorum) {
            emit WithdrawalQuorumChanged(oldWithdrawalQuorum, newWithdrawalQuorum);
        }
    }

    /**
     * @notice Sets the domain separators for EIP-712 signatures.
     * @param domainSeparator: The value to set.
     * @dev Reverts with `NotOwner`; Only the admin can set the domain separator.
     */
    function setDomainSeparator(bytes32 domainSeparator) external {
        if (msg.sender != owner) revert NotOwner();
        require(_domainSeparator == 0); // dev: Already set.
        _domainSeparator = domainSeparator;
    }

    /**
     * @notice Sets the settle executor.
     * @param settler: The settler's tplus account key.
     * @param executor: The settler's assigned executor address.
     * @dev Reverts with `NotOwner`; Only the admin can set the settler executor.
     */
    function addSettlerExecutor(bytes32 settler, address executor) external {
        if (msg.sender != owner) revert NotOwner();

        if (!settlerIsApproved[settler]) {
            approvedSettlers.push(settler);
            settlerIsApproved[settler] = true;
        }

        SettlerInfo storage data = settlerExecutorMap[settler];
        if (!data.isExecutor[executor]) {
            data.executors.push(executor);
            data.isExecutor[executor] = true;
        }
    }

    /**
     * @notice Removes a settler.
     * @param settler: The settler's tplus account key.
     * @dev Reverts with `NotOwner`; Only the admin can remove a settler.
     */
    function removeSettler(bytes32 settler) external {
        if (msg.sender != owner) revert NotOwner();
        uint256 length = approvedSettlers.length;

        settlerIsApproved[settler] = false;

        for (uint256 i = 0; i < length; i++) {
            if (approvedSettlers[i] == settler) {
                // Move last element to this spot and pop the last element.
                approvedSettlers[i] = approvedSettlers[length - 1];
                approvedSettlers.pop();
                break;
            }
        }

        // Remove all executors.
        SettlerInfo storage info = settlerExecutorMap[settler];
        for (uint256 i = 0; i < info.executors.length; i++) {
            address exec = info.executors[i];
            info.isExecutor[exec] = false;
        }
        delete info.executors;
    }

    /**
     * @notice Deposits a token into the vault.
     * @param user: The user whose account will be credited with the deposit.
     * @param tokenAddress: The address of the token to deposit.
     * @param amount: The amount of the token to deposit.
     * @dev Reverts if the amount is 0.
     */
    function deposit(bytes32 user, address tokenAddress, uint256 amount) external {
        uint256 nonce = _deposit(user, tokenAddress, amount);
        emit Deposited(user, nonce, tokenAddress, amount);
    }

    /**
     * @notice Deposits a token into the vault with additional multisig signer configuration.
     * @param user: The user whose account will be credited with the deposit.
     * @param tokenAddress: The address of the token to deposit.
     * @param amount: The amount of the token to deposit.
     * @dev Reverts if the amount is 0.
     */
    function deposit(
        bytes32 user,
        address tokenAddress,
        uint256 amount,
        uint32 masterWeight,
        uint32 lowThreshold,
        uint32 mediumThreshold,
        uint32 highThreshold,
        SignerConfig[] calldata signers,
        bytes calldata masterConfigSignature
    ) external {
        uint256 nonce = _deposit(user, tokenAddress, amount);
        emit DepositedWithConfig(
            user,
            nonce,
            tokenAddress,
            amount,
            masterWeight,
            lowThreshold,
            mediumThreshold,
            highThreshold,
            signers,
            masterConfigSignature
        );
    }

    function _deposit(bytes32 user, address tokenAddress, uint256 amount)
        internal
        returns (uint64 nonce)
    {
        if (!canDeposit[msg.sender]) revert DepositorNotApproved();
        if (amount == 0) revert ZeroAmount();

        // Ensure the deposit amount won't overflow when the clearing engine
        // normalizes it to CLEARING_ENGINE_DECIMALS.
        uint8 decimals = _getDecimals(tokenAddress);
        if (decimals < CLEARING_ENGINE_DECIMALS) {
            uint256 scalingFactor = 10 ** (CLEARING_ENGINE_DECIMALS - decimals);
            if (amount > type(uint256).max / scalingFactor) revert NormalizationOverflow();
        } else if (decimals > CLEARING_ENGINE_DECIMALS) {
            uint256 scalingFactor = 10 ** (decimals - CLEARING_ENGINE_DECIMALS);
            if (amount < scalingFactor) revert NormalizationRoundsToZero();
        }

        nonce = depositCounts[user];
        if (nonce == 0) {
            uint256 minimumFirstDepositAmount = minFirstDepositAmounts[tokenAddress];
            if (amount < minimumFirstDepositAmount) {
                revert FirstDepositBelowMinimum(minimumFirstDepositAmount, amount);
            }
        }
        depositCounts[user] = nonce + 1;

        SafeTransferLib.safeTransferFrom(tokenAddress, msg.sender, address(this), amount);
        return nonce;
    }

    function _getDecimals(address tokenAddress) internal view returns (uint8) {
        (bool success, bytes memory data) =
            tokenAddress.staticcall(abi.encodeWithSignature("decimals()"));
        if (!success || data.length < 32) revert DecimalsCallFailed();
        return abi.decode(data, (uint8));
    }

    // TODO: Delete this method and notion of approved-depositor before official production.
    function setDepositorStatus(address depositor, bool allowed) external {
        if (msg.sender != owner) revert NotOwner();
        canDeposit[depositor] = allowed;
    }

    /**
     * @notice Sets the minimum first-deposit amount for a token on this vault.
     * @dev This is intentionally vault-local so each chain can be configured without cross-chain registry reads.
     * @dev Callable by owner (bootstrap), credential manager, or vault administrators.
     */
    function setMinFirstDepositAmount(address tokenAddress, uint256 minimumAmount) external {
        if (msg.sender != owner && msg.sender != credentialManager && !isAdministrator(msg.sender))
        {
            revert NotVaultConfigManager();
        }
        if (tokenAddress == address(0)) revert ZeroAddress();

        uint256 previous = minFirstDepositAmounts[tokenAddress];
        minFirstDepositAmounts[tokenAddress] = minimumAmount;
        emit MinFirstDepositAmountChanged(tokenAddress, previous, minimumAmount);
    }

    /**
     * @notice Executes an atomic settlement.
     * @param order: The settlement order.
     * @param settler: The t+ identity of the settler executing this order.
     * @param data: The data to execute as part of settlement callback.
     * @param signature: The signature from the t+ clearing engine.
     * @dev Reverts with `Expired` if the block timestamp is greater than `validUntil`.
     * @dev Reverts with `SettlerNotApproved` if the settler is not in the approved set.
     * @dev Reverts with `NotExecutor`; Only the executor can settle.
     * @dev Reverts with `InvalidNonce` if the nonce has already been used.
     * @dev Reverts with `InvalidSignature` if the signer is not an admin.
     * @dev Reverts with `InsufficientAmountFromExecutor` if the `order.amountIn` is less than what the executor reports
     */
    function executeAtomicSettlement(
        Settlement calldata order,
        bytes32 settler,
        bytes calldata data,
        bytes calldata signature
    ) external {
        bytes32 user = order.user;
        uint64 account = order.account;
        uint256 validUntil = order.validUntil;

        if (block.timestamp > validUntil) revert Expired();
        if (!settlerIsApproved[settler]) revert SettlerNotApproved();
        if (!settlerExecutorMap[settler].isExecutor[msg.sender]) revert NotExecutor();

        uint256 expectedNonce = settlementCounts[user][account];
        if (order.nonce != expectedNonce) revert InvalidNonce(expectedNonce, order.nonce);

        bytes32 digest = keccak256(
            bytes.concat(
                SETTLEMENT_TYPEHASH,
                _domainSeparator,
                bytes32(uint256(uint160(order.tokenOut)) << 96),
                bytes32(order.amountOut),
                bytes32(uint256(uint160(order.tokenIn)) << 96),
                bytes32(order.amountIn),
                bytes32(uint256(uint8(order.mode))),
                user,
                bytes32(uint256(uint160(account))),
                bytes32(uint256(order.nonce)),
                bytes32(validUntil),
                settler
            )
        );

        // Check the signature and record latest signature usage if it's valid
        checkApproval(digest, signature);
        lastSignatureUse = block.number;

        // Ensure to bump the nonce _before_ the callback to avoid signature replay.
        settlementCounts[user][account] += 1;

        // Invoke callback on the executor
        uint256 expectedAmountIn = IAtomicSettlementCallback(msg.sender)
            .onAtomicSettlement(order.tokenOut, order.amountOut, data);
        if (expectedAmountIn < order.amountIn) {
            revert InsufficientAmountFromExecutor(expectedAmountIn, order.amountIn);
        }

        // Transfer tokens IN from the executor
        SafeTransferLib.safeTransferFrom(order.tokenIn, msg.sender, address(this), expectedAmountIn);

        // Transfer tokens OUT to the executor
        SafeTransferLib.safeTransfer(order.tokenOut, msg.sender, order.amountOut);

        emit Settled(
            user,
            account,
            order.nonce,
            order.tokenOut,
            order.amountOut,
            order.tokenIn,
            order.amountIn,
            order.mode,
            settler
        );
    }

    /// @notice Execute a sequence of settlement requests in a squashing fashion
    /// @param requests List of settlement requests
    function executeSquashingSettlements(
        SignedSettlement[] calldata requests,
        bytes[] calldata data,
        bytes32 settler
    ) external {
        address caller = msg.sender;
        uint256 numRequests = requests.length;
        uint256 numDataPayloads = data.length;
        if (numRequests != numDataPayloads) revert PayloadMismatch();

        /**
         * SAFETY(jmcph4): Check that settler is approved
         *
         * This prevents unauthorised settlers from executing settlements.
         */
        if (!settlerIsApproved[settler]) revert SettlerNotApproved();

        /**
         * SAFETY(jmcph4): Check that the caller is an assigned executor for this settler
         *
         * This prevents unauthorised execution of valid settlement requests.
         */
        if (!settlerExecutorMap[settler].isExecutor[caller]) revert NotExecutor();

        // Allocate token balances for netting off
        TokenSquashingBalance[] memory balances = new TokenSquashingBalance[](numRequests * 2);
        uint256 numUniqueTokens = 0;

        for (uint256 i = 0; i < numRequests; i++) {
            SignedSettlement memory currRequest = requests[i];
            bytes32 user = currRequest.settlement.user;
            uint64 account = currRequest.settlement.account;
            uint64 actualNonce = currRequest.settlement.nonce;
            uint256 validUntil = currRequest.settlement.validUntil;
            address tokenIn = currRequest.settlement.tokenIn;
            address tokenOut = currRequest.settlement.tokenOut;
            uint256 amountIn = currRequest.settlement.amountIn; /* TODO(jmcph4): callback */
            uint256 amountOut = currRequest.settlement.amountOut;

            /**
             * SAFETY(jmcph4): Check expiry
             *
             * This prevents stale settlement requests from being executed.
             */
            if (block.timestamp > validUntil) revert Expired();

            /**
             * SAFETY(jmcph4): Check nonce
             *
             * This prevents replay attacks on settlement requests.
             */
            uint256 expectedNonce = settlementCounts[user][account];
            if (actualNonce < expectedNonce) revert InvalidNonce(expectedNonce, actualNonce);

            bytes32 digest = keccak256(
                bytes.concat(
                    SETTLEMENT_TYPEHASH,
                    _domainSeparator,
                    bytes32(uint256(uint160(tokenOut)) << 96),
                    bytes32(amountOut),
                    bytes32(uint256(uint160(tokenIn)) << 96),
                    bytes32(amountIn),
                    bytes32(uint256(uint8(currRequest.settlement.mode))),
                    user,
                    bytes32(uint256(uint160(account))),
                    bytes32(uint256(actualNonce)),
                    bytes32(validUntil)
                )
            );

            /**
             * SAFETY(jmcph4): Verify t+ Clearing Engine (CE) signature
             *
             * This prevents unauthorised settlements.
             */
            checkApproval(digest, requests[i].clearingEngineSignature); /* TODO(jmcph4): horrific calldata load */
            lastSignatureUse = block.number;

            /**
             * SAFETY(jmcph4): Increment settlement nonce prior to invoking the
             *                  callback
             *
             * This prevents replay attacks (reentrant or otherwise) on
             * settlement requests.
             */
            settlementCounts[user][account] = actualNonce + 1;

            // Apply this request to running net token balances
            bool inputFound = false;
            bool outputFound = false;
            for (uint256 j = 0; j < numUniqueTokens; j++) {
                if (balances[j].token == tokenIn) {
                    balances[j].input += amountIn;
                    inputFound = true;
                    break;
                }
            }

            if (!inputFound) {
                balances[numUniqueTokens] = TokenSquashingBalance(tokenIn, amountIn, 0, 0);
                numUniqueTokens++;
            }

            for (uint256 j = 0; j < numUniqueTokens; j++) {
                if (balances[j].token == tokenOut) {
                    balances[j].output += amountOut;
                    outputFound = true;
                    break;
                }
            }

            if (!outputFound) {
                balances[numUniqueTokens] = TokenSquashingBalance(tokenOut, 0, amountOut, 0);
                numUniqueTokens++;
            }
        }

        // Net off each token balance
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            if (balances[i].input > balances[i].output) {
                balances[i].netAmount = int256(balances[i].input - balances[i].output);
            } else if (balances[i].output > balances[i].input) {
                balances[i].netAmount = -int256(balances[i].output - balances[i].input);
            }
        }

        // Push funds out from the vault and into the executor
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            // Negative net amount implies that we must push funds out from the vault
            if (balances[i].netAmount < 0) {
                // Transfer tokens OUT to the executor
                SafeTransferLib.safeTransfer(
                    balances[i].token, caller, uint256(-balances[i].netAmount)
                );
            }
        }

        // Call callbacks and record return values
        uint256[] memory callbackReturns = new uint256[](numRequests);

        for (uint256 i = 0; i < numRequests; i++) {
            Settlement memory request = requests[i].settlement;

            /**
             * SAFETY(jmcph4): Record callback return value
             *
             * The executor reports how much of tokenIn it will provide for this
             * specific settlement. Pass the per-settlement amountOut, not the net.
             * These values will be validated against requirements before pulling funds.
             */
            callbackReturns[i] = IAtomicSettlementCallback(msg.sender)
                .onAtomicSettlement(request.tokenOut, request.amountOut, data[i]);

            /**
             * SAFETY(jmcph4): Validate per-settlement callback return
             *
             * Ensure the executor commits to provide at least the promised amountIn
             * for THIS specific settlement. This prevents cross-settlement subsidization
             * where an executor could shortchange one user while overpaying another.
             */
            if (callbackReturns[i] < request.amountIn) {
                revert InsufficientCallbackReturnForSettlement(
                    i, callbackReturns[i], request.amountIn
                );
            }
        }

        // Validate callback returns and pull funds
        for (uint256 i = 0; i < numUniqueTokens; i++) {
            // Only process tokens that need to be pulled (positive net amount)
            if (balances[i].netAmount > 0) {
                address token = balances[i].token;
                uint256 requiredAmount = uint256(balances[i].netAmount);

                /**
                 * SAFETY(jmcph4): Sum callback returns by token
                 *
                 * Calculate total amount the executor has committed to provide
                 * for this token across all settlements.
                 */
                uint256 totalCallbackAmount = 0;
                for (uint256 j = 0; j < numRequests; j++) {
                    if (requests[j].settlement.tokenIn == token) {
                        totalCallbackAmount += callbackReturns[j];
                    }
                }

                /**
                 * SAFETY(jmcph4): Validate executor commitment
                 *
                 * Ensure the executor has committed to provide at least the
                 * required net amount for this token.
                 */
                if (totalCallbackAmount < requiredAmount) {
                    revert InsufficientAmountFromExecutor(totalCallbackAmount, requiredAmount);
                }

                // Transfer tokens IN from the executor
                SafeTransferLib.safeTransferFrom(token, caller, address(this), requiredAmount);
            }
        }

        // Emit settlement events
        for (uint256 i = 0; i < numRequests; i++) {
            Settlement memory request = requests[i].settlement;

            /**
             * SAFETY(jmcph4): Emit per-settlement amounts
             *
             * Events must reflect the actual per-settlement amounts, not the netted
             * amounts. This ensures proper accounting and allows off-chain systems
             * to correctly track what each user received.
             */
            emit Settled(
                request.user,
                request.account,
                request.nonce,
                request.tokenOut,
                request.amountOut,
                request.tokenIn,
                request.amountIn,
                request.mode,
                settler
            );
        }
    }

    /**
     * @notice Pulls funds for execution during a settlement batch.
     * @param orders: The settlement orders.
     * @param user: The t+ user who is executing the settlement.
     * @param target: The target address to send the token to, pull tokens from, and execute callback on.
     * @param validUntil: The timestamp when the settlement signature expires.
     * @dev Reverts with `Expired` if the block timestamp is greater than `validUntil`.
     * @dev Reverts if a batch settlement has already started.
     * @dev Reverts with `NotAdmin`; Only an admin can execute the settlement.
     * @dev Reverts with `InvalidNonce` if the nonce has already been used.
     * @dev Reverts with `SignatureError` if the signer is not an admin.
     */
    function pullBatchSettlements(
        SignedSettlementOrder[] calldata orders,
        bytes32 user,
        uint64 account,
        address target,
        uint256 validUntil
    ) external {
        if (block.timestamp > validUntil) revert Expired();
        require(pendingSettlements[user][account].length == 0);
        if (!isAdministrator(msg.sender)) revert NotAdmin();

        uint256 expectedNonce = settlementCounts[user][account];
        bytes32 domainSeparator = _domainSeparator;
        uint64 ordersLength = uint64(orders.length);
        if (ordersLength == 0) revert EmptyOrders();

        for (uint256 i = 0; i < ordersLength; ++i) {
            SettlementOrder calldata s = orders[i].settlement;

            uint256 nonce = s.nonce;
            if (nonce != expectedNonce) revert InvalidNonce(expectedNonce, nonce);

            bytes32 digest = keccak256(
                bytes.concat(
                    SETTLEMENT_TYPEHASH,
                    domainSeparator,
                    bytes32(uint256(uint160(s.tokenOut)) << 96),
                    bytes32(s.amountOut),
                    bytes32(uint256(uint160(s.tokenIn)) << 96),
                    bytes32(s.amountIn),
                    bytes32(uint256(uint8(s.mode))),
                    user,
                    bytes32(uint256(uint160(account))),
                    bytes32(uint256(s.nonce)),
                    bytes32(validUntil)
                )
            );

            checkApproval(digest, orders[i].clearingEngineSignature);
            expectedNonce = nonce + 1;

            pendingSettlements[user][account].push(
                PendingSettlement({settlement: s, target: target})
            );
            SafeTransferLib.safeTransfer(s.tokenOut, target, s.amountOut);
        }

        settlementCounts[user][account] += ordersLength;
    }

    /**
     * @notice Pushes expected funds from a batch settlement to the deposit vault.
     * @param user: The t+ user who is executing the settlement.
     * @param account: The account of the t+ user to execute settlement against
     * @dev Reverts with `NotAdmin`; Only an admin can execute the settlement.
     */
    function pushBatchSettlements(bytes32 user, uint64 account) external {
        if (!isAdministrator(msg.sender)) revert NotAdmin();

        for (uint32 i = 0; i < pendingSettlements[user][account].length; i++) {
            PendingSettlement memory pendingSettlement = pendingSettlements[user][account][i];

            SafeTransferLib.safeTransferFrom(
                pendingSettlement.settlement.tokenIn,
                pendingSettlement.target,
                address(this),
                pendingSettlement.settlement.amountIn
            );
            emit Settled(
                user,
                account,
                pendingSettlement.settlement.nonce,
                pendingSettlement.settlement.tokenOut,
                pendingSettlement.settlement.amountOut,
                pendingSettlement.settlement.tokenIn,
                pendingSettlement.settlement.amountIn,
                pendingSettlement.settlement.mode,
                bytes32(0)
            );
        }
        delete pendingSettlements[user][account];
    }

    /**
     * @notice Withdraws a token from the vault.
     * @param withdrawal: The withdrawal token and amount.
     * @param user: The user whose account will be debited by the withdrawal.
     * @param target: The target address to send the token to.
     * @param validUntil: The timestamp when the withdrawal signature expires.
     * @param signatures: t+ clearing engine signatures.
     * @dev Reverts with `Expired` if the block timestamp is greater than `validUntil`.
     * @dev Reverts with `InvalidNonce` if the nonce has already been used.
     * @dev Reverts with `SignatureError` if the signer is not an admin.
     */
    function withdraw(
        Withdrawal calldata withdrawal,
        bytes32 user,
        address target,
        uint256 validUntil,
        bytes32 epochHash,
        bytes[] calldata signatures
    ) external {
        /* PERF(jmcph4): cache storage variable to the stack */
        uint256 quorum = withdrawalQuorum;
        if (block.timestamp > validUntil) revert Expired();
        if (signatures.length < withdrawalQuorum) {
            revert MissedQuorum(signatures.length, quorum);
        }

        uint256 expectedNonce = withdrawalCounts[user];
        if (withdrawal.nonce < expectedNonce) {
            revert InvalidNonce(expectedNonce, withdrawal.nonce);
        }

        /**
         * BEGIN SIGNATURE CHECKS *************************
         */

        // Set of administrators that have provided signatures for this withdrawal
        address[] memory seenAdmins = new address[](signatures.length);
        uint256 numSeenAdmins = 0;

        // PERF(jmcph4): No need to recompute inside the loop body
        bytes32 digest = keccak256(
            bytes.concat(
                WITHDRAWAL_TYPEHASH,
                _domainSeparator,
                bytes32(uint256(uint160((withdrawal.tokenAddress))) << 96),
                bytes32(withdrawal.amount),
                user,
                bytes32(uint256(withdrawal.nonce)),
                bytes32(validUntil),
                bytes32(epochHash),
                bytes32(uint256(uint160(target)) << 96)
            )
        );

        for (uint256 i = 0; i < signatures.length; i++) {
            /* Verify the signature.
             *
             * This determines whether the digest is really signed by the provided
             * signature and computes the signer's address.
             */
            address signer = ECDSA.tryRecoverCalldata(digest, signatures[i]);
            if (signer == address(0)) revert InvalidSignature();

            // Check that the recovered signer is in fact an administrator
            if (!isAdministrator(signer)) revert InvalidSignature();

            /* Check that this administrator is unique. Without this step, a
             * single admin could provide `k` signatures where `k == withdrawalQuorum`
             * and we'd happily approve the withdrawal.
             */
            bool isCurrentSignerUnique = true;
            for (uint256 j = 0; j < numSeenAdmins; j++) {
                if (seenAdmins[j] == signer) {
                    isCurrentSignerUnique = false;
                    break;
                }
            }
            if (isCurrentSignerUnique) {
                seenAdmins[numSeenAdmins] = signer;
                numSeenAdmins++;
            }
            if (numSeenAdmins == quorum) break;
        }

        if (numSeenAdmins < quorum) revert MissedQuorum(numSeenAdmins, quorum);

        /**
         * END SIGNATURE CHECKS *************************
         */

        // SAFETY(jmcph4): Purposely bump the nonce as close to signature verification as possible, to alleviate callback concerns.
        withdrawalCounts[user] = withdrawal.nonce + 1;

        // Record latest signature usage
        lastSignatureUse = block.number;

        SafeTransferLib.safeTransfer(withdrawal.tokenAddress, target, withdrawal.amount);
        emit Withdrew(user, withdrawal.nonce, withdrawal.tokenAddress, withdrawal.amount);
    }

    /**
     * @notice Get the array of approved settlers.
     * @return An array of addresses (as bytes32) that are currently approved settlers.
     */
    function getApprovedSettlers() external view returns (bytes32[] memory) {
        return approvedSettlers;
    }

    // TODO: Delete this method before official production.
    function ownerWithdrawToken(address token, address to, uint256 amount) external {
        if (msg.sender != owner) revert NotOwner();
        require(to != address(0));
        SafeTransferLib.safeTransfer(token, to, amount);
    }

    function checkApproval(bytes32 digest, bytes calldata signature) internal view {
        address signer = ECDSA.tryRecoverCalldata(digest, signature);
        if (signer == address(0)) revert InvalidSignature();
        if (!isAdministrator(signer)) revert InvalidSignature();
    }
}

