src/interfaces/IAutomataDcapAttestation..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice Interface for Automata's DCAP Attestation Verifier.
/// @dev Bindings for the deployed 'AutomataDcapAttestationFee' entrypoint.
interface IAutomataDcapAttestation {
    // NB: must match Automata's AttestationEntrypointBase enum EXACTLY. the ordinal is
    // abi-encoded and sent on-chain (None=0, RiscZero=1, Succinct=2); dropping None shifts
    // Succinct to 1, which the deployed verifier reads as RiscZero -> wrong program id ->
    // SP1 proof verification fails.
    enum ZkCoProcessorType {
        None,
        RiscZero,
        Succinct // SP1
    }

    /// @notice Verifies a SNARK proof (Groth16) for a TEE Quote.
    /// @param output The Public Values (Journal) - effectively the Quote Body.
    /// @param zkvm The type of ZKVM used.
    /// @param proofBytes The actual (Groth16) proof.
    /// @return success True if valid.
    /// @return errorData Error message if failed, or empty if success.
    function verifyAndAttestWithZKProof(
        bytes calldata output,
        ZkCoProcessorType zkvm,
        bytes calldata proofBytes
    ) external returns (bool success, bytes memory errorData);

    /// @notice Full on-chain DCAP verification of a raw quote (no ZK). Used on chains where the
    ///         ZK coprocessor is not configured (e.g. Arbitrum). The verifier validates the Intel
    ///         cert chain + CRLs + TCB level + QE identity + measurements against on-chain PCCS.
    /// @param rawQuote The full DCAP quote (header + body + signature + cert chain).
    /// @param tcbEvaluationDataNumber Intel TCB evaluation number to verify against.
    /// @return success True if valid.
    /// @return output On success, the serialized verified Output:
    ///         quoteVersion(2) ‖ quoteBodyType(2) ‖ tcbStatus(1) ‖ fmspc(6) ‖ tdReportBody(>=584).
    ///         On failure, the error reason. NB: deployed entrypoint is `payable` (fee bp may be 0).
    function verifyAndAttestOnChain(bytes calldata rawQuote, uint32 tcbEvaluationDataNumber)
        external
        returns (bool success, bytes memory output);
}

